n = 0:15;
x = 0.8.^n;
figure
stem(n, x, 'filled'); xlabel('n'); ylabel('x[n]'); title('x[n] = 0.8^n'); grid on

A = 5; f = 50; phi = pi/4;
t = linspace(0, 3/f, 600);
figure
plot(t*1e3, A*cos(2*pi*f*t + phi)); grid on
xlabel('t (ms)'); ylabel('v (V)'); title(sprintf('A = %g V, f = %g Hz, phase = %g deg', A, f, phi*180/pi))
